#include <limits.h>
#include <stddef.h>
#include <stdio.h>

static int average_score(const int scores[], size_t count, int *average_out)
{
    size_t i;
    long long total = 0;

    if (average_out == NULL || (count > 0U && scores == NULL)) {
        return 0;
    }
    if (count == 0U) {
        return 0;
    }
    for (i = 0U; i < count; ++i) {
        if (scores[i] < 0 || scores[i] > 100 ||
            total > LLONG_MAX - (long long)scores[i]) {
            return 0;
        }
        total += (long long)scores[i];
    }
    *average_out = (int)(total / (long long)count);
    return 1;
}

int main(void)
{
    const int scores[] = {72, 85, 91, 68};
    int average = -1;

    if (!average_score(scores, sizeof scores / sizeof scores[0], &average)) {
        fputs("invalid score data\n", stderr);
        return 1;
    }
    printf("average=%d\n", average);
    return 0;
}

#include <stddef.h>
#include <stdio.h>

static int find_first(const int values[], size_t count, int target,
                      size_t *index_out)
{
    size_t i;

    if (index_out == NULL || (count > 0U && values == NULL)) {
        return 0;
    }
    for (i = 0U; i < count; ++i) {
        if (values[i] == target) {
            *index_out = i;
            return 1;
        }
    }
    return 0;
}

int main(void)
{
    const int readings[] = {18, 21, 21, 24, 27};
    const size_t count = sizeof readings / sizeof readings[0];
    size_t index = 999U;

    if (find_first(readings, count, 21, &index)) {
        printf("found at index %zu\n", index);
    } else {
        puts("not found");
    }

    if (!find_first(readings, count, 30, &index)) {
        puts("30 not found; index output unchanged");
    }
    return 0;
}
